One hundred years ago, the Black Dragon fell into the Eastern Sea, churning the water and washing wickedness from the earth. It rained for many months and peace returned for a time.
 
Creatures great and small gathered there, drawn to its might and its majesty.
 
But some of the visitors would not let it leave, trapping it there in the East where it languished.
 
Mortal heroes grew old and could not release it.
 
